const body = $input.item.json.body ?? $input.item.json;

// Ignore messages sent by the bot itself
if (body.payload?.fromMe === true) {
  return [{ json: { skip: true } }];
}

// Extract fields
const event       = body.event ?? 'message';
const sessionName = body.session ?? '';
const payload     = body.payload ?? {};

const fromRaw     = payload.from ?? '';
const chatId      = fromRaw;
const phoneNumber = fromRaw.replace('@c.us', '').replace('@g.us', '').replace('@lid', '');
const messageText = payload.body ?? payload.text ?? '';
const timestamp   = payload.timestamp ? new Date(payload.timestamp * 1000).toISOString() : new Date().toISOString();
const messageId   = payload.id ? String(payload.id) : `fallback_${timestamp}`;

if (!messageText.trim()) {
  return [{ json: { skip: true, reason: 'no_text' } }];
}

return [{
  json: {
    skip: false,
    sessionName,
    phoneNumber,
    chatId,
    messageText,
    messageId,
    timestamp,
    event
  }
}];

const contextMessages = $input.all();
const businessData    = $('Get Business by Session').item.json;
const normalized      = $('Normalize Payload').item.json;
const customerState   = $('Get Customer State').item?.json?.active_flow || 'NONE';

const historyLines = contextMessages
  .slice(0, 3)
  .map(m => `[${m.json.direction.toUpperCase()}]: ${m.json.message_text}`)
  .join('\n');

return [{
  json: {
    business_id:   businessData.business_id,
    business_name: businessData.business_name,
    phoneNumber:   normalized.phoneNumber,
    chatId:        normalized.chatId,
    messageText:   normalized.messageText,
    active_flow:   customerState,
    contextHistory: historyLines || '(no prior conversation)',
    prompt: `Business: ${businessData.business_name}\nCustomer State: ${customerState}\n\nConversation history (most recent first):\n${historyLines || '(no prior conversation)'}\n\nCustomer message: ${normalized.messageText}`
  }
}];

// Robust Classification Parser
const rawResponse = $input.item.json.output ?? $input.item.json.text ?? '';
const ctx = $('Build AI Context').item.json;
const msgText = (ctx.messageText || '').trim().toLowerCase();

let classification = null;

// 1. Direct hardcoded check for common greetings and thank-you messages
const greetings = [
  'hi', 'hello', 'hey', 'good morning', 'good evening', 'hii', 'hiii', 'yo', 'sup', 'whatsup', 'hi there', 'hello there',
  'thanks', 'thank you', 'tnk you', 'tnx', 'ok thank you', 'ok tnk you', 'ok thanks', 'thank u', 'ok thank u'
];
if (greetings.includes(msgText)) {
  classification = {
    intent: 'GENERAL_QUESTION',
    confidence: 1.0,
    entities: {},
    language: 'en'
  };
} else {
  // 2. Try parsing ReAct or standard JSON output from Gemini
  try {
    let textToParse = rawResponse;
    if (typeof rawResponse === 'string' && rawResponse.includes('"action_input"')) {
      try {
        const reactObj = JSON.parse(rawResponse);
        textToParse = reactObj.action_input || rawResponse;
      } catch(e) {}
    }

    const cleaned = textToParse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
    const jsonStr = jsonMatch ? jsonMatch[0] : cleaned;
    classification = JSON.parse(jsonStr);
  } catch (e) {
    // If classification JSON parsing fails, treat as GENERAL_QUESTION with 1.0 confidence so it goes to AI response, NEVER human handoff
    classification = {
      intent: 'GENERAL_QUESTION',
      confidence: 1.0,
      entities: {},
      language: 'en'
    };
  }
}

return [{
  json: {
    ...ctx,
    intent:     classification.intent     || 'GENERAL_QUESTION',
    confidence: classification.confidence ?? 1.0,
    entities:   classification.entities   || {},
    language:   classification.language   || 'en'
  }
}];

parameters.query:
UPDATE conversations
SET detected_intent = '{{ $json.intent }}', confidence = {{ $json.confidence || 0 }}
WHERE business_id = '{{ $("Get Business by Session").first().json.business_id }}' AND customer_number = '{{ $("Normalize Payload").first().json.phoneNumber }}'
  AND created_at = (SELECT MAX(created_at) FROM conversations WHERE business_id = '{{ $("Get Business by Session").first().json.business_id }}' AND customer_number = '{{ $("Normalize Payload").first().json.phoneNumber }}');

