const allItems = $input.all();
const parentData = $('Workflow Input').item?.json ?? {};
const products = allItems.map(item => item.json);
const inStock  = products.filter(p => p.stock > 0);
return [{
  json: {
    products_json: JSON.stringify(products),
    in_stock_count: inStock.length,
    has_products: products.length > 0,
    business_id: parentData.business_id,
    business_name: parentData.business_name,
    intent: parentData.intent,
    language: parentData.language,
    chatId: parentData.chatId,
    phoneNumber: parentData.phoneNumber,
    messageText: parentData.messageText,
    contextHistory: parentData.contextHistory || '(no prior conversation)',
    discount_json: 'null',
    pricing_json: 'null'
  }
}];

const parentData = $('Workflow Input').item?.json ?? {};
return [{
  json: {
    products_json: JSON.stringify([{ name: 'Item', stock: 0, description: 'Currently out of stock' }]),
