// Send product image via WAHA API
const chatId = $json.chatId;
const imageUrl = $json.imageUrl;
const replyText = String($json.replyText || '');
const session = 'fashion-gallery';
const wahaUrl = 'http://waha:3000';
const apiKey = 'CHANGE_ME_waha_api_key_here';

const result = await this.helpers.httpRequest({
  method: 'POST',
  url: wahaUrl + '/api/sendImage',
  json: true,
  headers: {
    'X-Api-Key': apiKey,
    'Content-Type': 'application/json'
  },
  body: {
    session: session,
    chatId: chatId,
    file: { url: imageUrl },
    caption: replyText
  }
});

return [{ json: result }];

let ctx = {};
try {
  ctx = $('Prepare AI Input').item?.json || {};
} catch(e) {
  try {
    ctx = $('Out of Stock Path').item?.json || {};
  } catch(e2) {}
}

// 1. Get raw text output
const rawText = String($input.item?.json?.text || $input.item?.json?.output || '');

// 2. STRIP ALL LEADING SPACES & TABS FROM EVERY LINE!
const replyText = rawText.replace(/^[ \t]+/gm, '').trim();

let products = [];
try {
  if (typeof ctx.products_json === 'string') {
    products = JSON.parse(ctx.products_json);
  } else if (Array.isArray(ctx.products_json)) {
    products = ctx.products_json;
  }
} catch(e) {
  products = [];
}

const messageText = String(ctx.messageText || '').toLowerCase();

const isPhotoRequest = /photo|image|picture|show|see|look|view|pic/i.test(messageText);
const isSingleProduct = products.length === 1;
const isSpecificProduct = !!($('Workflow Input').item?.json?.entities?.product_name);

// Smart Match: Find the product whose name appears inside the AI's reply message
let matchedProduct = products.find(p => p && p.name && replyText.toLowerCase().includes(p.name.toLowerCase()));
if (!matchedProduct && products.length > 0) {
  matchedProduct = products[0]; // fallback to first item
}

let hasImage = false;
let imageUrl = '';

if (matchedProduct && matchedProduct.image_url && (isPhotoRequest || isSingleProduct || isSpecificProduct)) {
  hasImage = true;
  imageUrl = matchedProduct.image_url;
}

return {
  json: {
    replyText: replyText,
    hasImage: hasImage,
    imageUrl: imageUrl,
    chatId: ctx.chatId || $('Workflow Input').item?.json?.chatId,
    session: ctx.session || 'fashion-gallery'
  }
};

// Â§10.3 Node 3: Calculate pricing breakdown (JavaScript)
// Never stacks multiple rules â€” applies the single best match.

const products = $('Fetch Products for Bulk').all().map(i => i.json);
const discount  = $('Fetch Discount Rule').first()?.json ?? null;
const parentCtx = $('Workflow Input').first()?.json ?? {};

const quantity  = parentCtx.entities?.quantity ?? 1;
const product   = products[0]; // primary match

if (!product) {
  return [{
    json: {
      ...parentCtx,
      pricingError:  true,
      products_json: JSON.stringify([]),
      discount_json: JSON.stringify(discount),
      pricing_json:  JSON.stringify(null)
    }
  }];
}

if (product.stock < quantity) {
  return [{
    json: {
      ...parentCtx,
      pricingError:  true,
      stockError:    true,
      products_json: JSON.stringify([product]),
      discount_json: 'null',
      pricing_json:  JSON.stringify({
        error: `Requested ${quantity}, but only ${product.stock} available in stock.`
      })
    }
  }];
}

const unitPrice  = parseFloat(product.price);
const subtotal   = unitPrice * quantity;

let discountAmount = 0;
let finalTotal     = subtotal;
let discountLabel  = 'No discount';

if (discount) {
  if (discount.discount_type === 'percentage') {
    discountAmount = subtotal * (parseFloat(discount.discount_value) / 100);
    finalTotal     = subtotal - discountAmount;
    discountLabel  = `${discount.discount_value}% off`;
  } else if (discount.discount_type === 'fixed_price') {
    // fixed_price overrides unit price per item
    const fixedUnitPrice = parseFloat(discount.discount_value);
    finalTotal           = fixedUnitPrice * quantity;
    discountAmount       = subtotal - finalTotal;
    // Updated to Rs.
    discountLabel        = `Rs. ${discount.discount_value}/item (special price)`;
  }
}

const pricing = {
  product_name:    product.name,
  unit_price:      unitPrice.toFixed(2),
  quantity,
  subtotal:        subtotal.toFixed(2),
  discount_label:  discountLabel,
  discount_amount: discountAmount.toFixed(2),
  final_total:     finalTotal.toFixed(2),
  // Updated to LKR
  currency:        'LKR'
};

return [{
  json: {
    ...parentCtx,
    pricingError:  false,
    products_json: JSON.stringify(products),
    discount_json: JSON.stringify(discount ?? {}),
    pricing_json:  JSON.stringify(pricing)
  }
}];

// Parse AI Agent bulk order reply
// AI Agent node outputs the text in $input.item.json.output
const aiText = $input.item.json.output ?? $input.item.json.text ?? '';
const ctx = $('Calculate Bulk Pricing').item.json;

return [{
  json: {
    replyText:   aiText.trim(),
    chatId:      ctx.chatId,
    business_id: ctx.business_id,
    phoneNumber: ctx.phoneNumber
  }
}];

// Order Confirmation Entry
const ctx = $input.item.json;
return [{ json: {
    ...ctx
} }];

// Build context for checkout AI
const ctx = $('Order Confirmation Entry').item.json;

// The parent workflow (01_incoming_message_router) already passed historyText
// inside ctx. We don't need to overwrite it. Just pass ctx along.

return [{ json: {
    ...ctx
} }];

// Parse the AI Agent delivery info response
let raw = '';
if (typeof $input.item?.json === 'string') raw = $input.item.json;
else if ($input.item?.json?.text) raw = $input.item.json.text;
else if ($input.item?.json?.output) raw = $input.item.json.output;
else if ($input.item?.json?.message?.content) raw = $input.item.json.message.content;
else if ($input.item?.json?.message) raw = $input.item.json.message;
else raw = JSON.stringify($input.item?.json || {});

const ctx = $('Build Checkout Context').item?.json || {};
const userMsg = String(ctx.messageText || '').trim();

let has_delivery = false;
let address = null;
let payment = 'cash_on_delivery';
let customer_name = null;
let customer_mobile = null;
let items = [];
let total_price = 0;

try {
    const jsonMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    const jsonStr = jsonMatch ? jsonMatch[1] : raw;
    const match = jsonStr.match(/\{[\s\S]*\}/);
    if (match) {
        let result = JSON.parse(match[0]);
        if (result.action_input && typeof result.action_input === 'string') {
            result = JSON.parse(result.action_input.match(/\{[\s\S]*\}/)[0]);
        }
        if (result.has_delivery_info === true || result.has_delivery_info === "true") has_delivery = true;
        if (result.delivery_address && result.delivery_address !== 'null' && result.delivery_address !== 'Provided in chat') address = result.delivery_address;
        if (result.payment_method) payment = result.payment_method;
        if (result.customer_name && result.customer_name !== 'null') customer_name = result.customer_name;
        if (result.customer_mobile && result.customer_mobile !== 'null') customer_mobile = result.customer_mobile;
        if (result.items) items = result.items;
        if (result.total_price) {
            let tp = parseFloat(String(result.total_price).replace(/,/g, ''));
            if (!isNaN(tp)) total_price = tp;
        }
    }
} catch(e) {}

// Fallback for customer_mobile from WhatsApp phoneNumber metadata
if (!customer_mobile && ctx.phoneNumber) {
    customer_mobile = ctx.phoneNumber.replace(/@.*/, '');
}
if (!address && has_delivery) {
    address = 'Provided in chat';
}

return [{ json: {
    ...ctx,
    has_delivery_info: has_delivery,
    delivery_address: address,
    payment_method: payment,
    customer_name: customer_name || 'Customer',
    customer_mobile: customer_mobile || 'Provided',
    items: items,
    total_price: total_price
} }];

// Build the order object with delivery details
const ctx = $('Parse Delivery Info').item?.json || {};

let itemsArray = (ctx.items && Array.isArray(ctx.items) && ctx.items.length > 0) 
  ? ctx.items 
  : [{ product_name: 'Order from chat', qty: 1, unit_price: 0 }];

let tp = parseFloat(ctx.total_price) || 0;
if (tp > 0 && tp < 1000) tp = tp * 300;

// Scan all messages in Fetch Chat History to find quoted prices, quantities, and product names
let allChat = [];
try {
    allChat = $('Fetch Chat History').all().map(i => i.json.message_text || '');
} catch(e) {}

let foundPrice = 0;
let foundQty = 0;
let foundProduct = '';

for (let msg of allChat) {
    // ðŸ”¥ NEW FIX: Stop scanning past previous orders!
    if (msg.includes('Order Confirmed & Placed!')) break;

    // 1. Check for Bulk Order Final Total (handles both "LKR 267,750" and "267750.00 LKR")
    if (!foundPrice) {
        const finalMatch = msg.match(/Final Total:\s*(?:LKR\s*)?([\d,]+(?:\.\d+)?)\s*(?:LKR)?/i) || msg.match(/Grand Total:\s*(?:LKR\s*)?([\d,]+(?:\.\d+)?)\s*(?:LKR)?/i);
        if (finalMatch) {
            foundPrice = parseFloat(finalMatch[1].replace(/,/g, ''));
        } else {
            const pMatch = msg.match(/(?:LKR\s*)?([\d,]+(?:\.\d+)?)\s*LKR/i) || msg.match(/LKR\s*([\d,]+(?:\.\d+)?)/i);
            if (pMatch) {
                const num = parseFloat(pMatch[1].replace(/,/g, ''));
                if (num > 0 && num !== 350) { // skip delivery fee
                    foundPrice = num;
                }
            }
        }
    }

    // 2. Check for Quantity in Bulk Quote: e.g. "Quantity: 60" or "Quantity: 70"
    if (!foundQty) {
        const qMatch = msg.match(/Quantity:\s*(\d+)/i) || msg.match(/(\d+)\s*pieces/i) || msg.match(/order of\s*(\d+)/i) || msg.match(/(\d+)\s*units/i);
        if (qMatch) {
            foundQty = parseInt(qMatch[1]) || 0;
        }
    }

    // 3. Find Product Name
    if (!foundProduct) {
        const products = [
            'Premium Cotton T-Shirt',
            'Polo T-Shirt',
            'V-Neck T-Shirt',
            'Cotton Bucket Hat',
            'Floral Midi Dress',
            'Casual Shirt Dress',
            'Denim Jacket',
            'Bomber Jacket',
            'Slim-Fit Chinos',
            'Formal Dress Trousers',
            'Canvas Tote Bag',
            'Evening Gown'
        ];
        for (let p of products) {
            if (msg.toLowerCase().includes(p.toLowerCase())) {
                foundProduct = p;
                break;
            }
        }
    }
}

// If this was a bulk order with a discovered final total & quantity:
if (foundPrice > 0) {
    tp = foundPrice;
}

if (foundQty > 1) {
    itemsArray = [{
        product_name: foundProduct || 'Bulk Order',
        qty: foundQty,
        unit_price: Math.round(tp / foundQty)
    }];
} else {
    // Normal retail order calculations
    const totalQty = itemsArray.reduce((sum, item) => sum + (parseInt(item.qty) || 1), 0) || 1;
    for (let i of itemsArray) {
        let up = parseFloat(i.unit_price) || 0;
        if (up > 0 && up < 1000) up = up * 300;
        if (up === 0 && tp > 0) {
            up = Math.round(tp / totalQty);
        }
        i.unit_price = up;

        let pName = (i.product_name || '').trim();
        if (foundProduct) {
            if (!pName || pName === 'Order from chat' || pName.toLowerCase().includes('size') || pName.toLowerCase().includes('color') || !pName.toLowerCase().includes(foundProduct.toLowerCase())) {
                i.product_name = pName ? (foundProduct + ' (' + pName + ')') : foundProduct;
            }
        }
    }
}

// Recompute total price from items
tp = itemsArray.reduce((sum, item) => sum + ((item.unit_price || 0) * (parseInt(item.qty) || 1)), 0);

return [{ json: {
    ...ctx,
    items: JSON.stringify(itemsArray),
    items_array: itemsArray,
    total_price: tp,
    discount_applied: 0.00,
    status: 'confirmed'
} }];

// Â§10.5 â€” Human Handoff entry point
// Triggered by: COMPLAINT, HUMAN_HANDOFF_REQUEST, or confidence < 0.6
const ctx = $input.item.json;

// Determine the handoff reason
let reason = 'low_confidence';
if (ctx.intent === 'COMPLAINT')              reason = 'complaint';
if (ctx.intent === 'HUMAN_HANDOFF_REQUEST') reason = 'customer_request';

return [{ json: { ...ctx, handoff_reason: reason } }];

// Build chat snapshot and AI context for the handoff
const ctx = $('Handoff Entry').item.json;
let chatArray = [];

// The Postgres node returns a single item with a 'chat_snapshot' property containing the array
try {
  const rawHistory = $input.item.json.chat_snapshot;
  if (Array.isArray(rawHistory)) {
    chatArray = rawHistory;
  } else if (typeof rawHistory === 'string') {
    chatArray = JSON.parse(rawHistory);
  }
} catch (e) {
  chatArray = [];
}

const chatSnapshot = chatArray.map(msg => ({
  direction:  msg.direction || 'unknown',
  text:       msg.message_text || '',
  intent:     msg.detected_intent || '',
  confidence: msg.confidence || 0,
  at:         msg.created_at || ''
}));

const chatText = chatArray
  .slice().reverse()
  .map(m => `[${(m.direction || 'unknown').toUpperCase()}] ${m.message_text || ''}`)
  .join('\n');

return [{
  json: {
    ...ctx,
    chat_snapshot: JSON.stringify(chatSnapshot),
    chat_text:     chatText || '(No previous messages)'
  }
}];

// Parse AI Agent suggested reply for handoff
const aiText = $input.item.json.output ?? $input.item.json.text ?? 'Our team will look into your concern and get back to you shortly.';
const ctx = $('Build Chat Snapshot').item.json;
const ticketId = $('Create Support Ticket').item.json.ticket_id;

return [{
  json: {
    ...ctx,
    ticket_id: ticketId,
    suggested_reply: aiText.trim()
  }
}];

